package video

import("encoding/json";"errors";"fmt";"net/url";"path/filepath";"strings";"time";"github.com/gin-gonic/gin";"github.com/google/uuid";"github.com/minio/minio-go/v7";"github.com/minio/minio-go/v7/pkg/credentials";"gorm.io/datatypes";"gorm.io/gorm";"github.com/fiap-x/video-platform/video-api/internal/config";"github.com/fiap-x/video-platform/video-api/internal/middleware")
type Job struct{ID uuid.UUID `gorm:"type:uuid;primaryKey" json:"id"`;UserID string `json:"-"`;OriginalFilename string;ContentType string;SizeBytes int64;InputObjectKey string;OutputObjectKey *string;Status string;ErrorCode *string;ErrorMessage *string;AttemptCount int;CreatedAt time.Time;UpdatedAt time.Time;StartedAt *time.Time;FinishedAt *time.Time}
func(Job)TableName()string{return "video_jobs"}
type createInput struct{Filename string `json:"filename"`;ContentType string `json:"contentType"`;SizeBytes int64 `json:"sizeBytes"`}
type API struct{db *gorm.DB; internal,public *minio.Client; cfg config.Config}
type OutboxEvent struct { ID uuid.UUID; AggregateID uuid.UUID; Type string; Payload datatypes.JSON; CreatedAt time.Time }
func(OutboxEvent)TableName()string{return "outbox_events"}
func New(db *gorm.DB,cfg config.Config)(*API,error){i,e:=minio.New(cfg.MinioInternalEndpoint,&minio.Options{Creds:credentials.NewStaticV4(cfg.MinioAccessKey,cfg.MinioSecretKey,""),Secure:false});if e!=nil{return nil,e};p,e:=minio.New(cfg.MinioPublicEndpoint,&minio.Options{Creds:credentials.NewStaticV4(cfg.MinioAccessKey,cfg.MinioSecretKey,""),Secure:false});if e!=nil{return nil,e};return &API{db:db,internal:i,public:p,cfg:cfg},nil}
func valid(in createInput,max int64)error{n:=filepath.Base(in.Filename);if n=="."||n==""||n!=in.Filename||len(n)>180{return errors.New("invalid filename")};if in.SizeBytes<=0||in.SizeBytes>max{return errors.New("invalid size")};ext:=strings.ToLower(filepath.Ext(n));allowed:=map[string]string{".mp4":"video/mp4",".mov":"video/quicktime",".avi":"video/x-msvideo",".mkv":"video/x-matroska",".webm":"video/webm"};if expected,ok:=allowed[ext];!ok||in.ContentType!=expected{return errors.New("unsupported video type")};return nil}
func (a *API) Create(c *gin.Context){var in createInput;if c.ShouldBindJSON(&in)!=nil||valid(in,a.cfg.MaxUploadBytes)!=nil{c.JSON(400,gin.H{"code":"invalid_upload","message":"Filename, video type or size is invalid"});return};id:=uuid.New();sub:=middleware.Subject(c);key:=fmt.Sprintf("uploads/%s/%s/source%s",sub,id,strings.ToLower(filepath.Ext(in.Filename)));job:=Job{ID:id,UserID:sub,OriginalFilename:in.Filename,ContentType:in.ContentType,SizeBytes:in.SizeBytes,InputObjectKey:key,Status:"AWAITING_UPLOAD"};if e:=a.db.Create(&job).Error;e!=nil{c.JSON(500,gin.H{"code":"storage_error"});return};u,e:=a.public.PresignedPutObject(c,a.cfg.InputBucket,key,a.cfg.PresignTTL);if e!=nil{_ = a.db.Delete(&job).Error;c.JSON(503,gin.H{"code":"upload_unavailable"});return};c.JSON(201,gin.H{"jobId":id,"uploadUrl":u.String(),"expiresInSeconds":int(a.cfg.PresignTTL.Seconds())})}
func(a *API)find(c *gin.Context)(Job,bool){id,e:=uuid.Parse(c.Param("id"));if e!=nil{c.JSON(404,gin.H{"code":"not_found"});return Job{},false};var j Job;if e=a.db.Where("id = ? AND user_id = ?",id,middleware.Subject(c)).First(&j).Error;e!=nil{c.JSON(404,gin.H{"code":"not_found"});return Job{},false};return j,true}
func(a *API)Confirm(c *gin.Context){j,ok:=a.find(c);if !ok{return};if j.Status=="PENDING"{c.JSON(200,gin.H{"id":j.ID,"status":j.Status});return};if j.Status!="AWAITING_UPLOAD"{c.JSON(409,gin.H{"code":"invalid_state","message":"Upload cannot be confirmed in this state"});return};info,e:=a.internal.StatObject(c,a.cfg.InputBucket,j.InputObjectKey,minio.StatObjectOptions{});if e!=nil||info.Size!=j.SizeBytes||info.ContentType!=j.ContentType{c.JSON(422,gin.H{"code":"invalid_uploaded_object","message":"Uploaded object is missing or does not match declared metadata"});return};eventID:=uuid.New();payload,_:=json.Marshal(map[string]any{"eventId":eventID,"eventType":"video.processing.requested","version":1,"jobId":j.ID,"occurredAt":time.Now().UTC()});if e:=a.db.Transaction(func(tx *gorm.DB)error{r:=tx.Model(&Job{}).Where("id = ? AND status = ?",j.ID,"AWAITING_UPLOAD").Updates(map[string]any{"status":"PENDING","updated_at":time.Now()});if r.Error!=nil{return r.Error};if r.RowsAffected!=1{return errors.New("concurrent transition")};return tx.Create(&OutboxEvent{ID:eventID,AggregateID:j.ID,Type:"video.processing.requested",Payload:payload}).Error});e!=nil{c.JSON(500,gin.H{"code":"storage_error"});return};c.JSON(200,gin.H{"id":j.ID,"status":"PENDING"})}
func(a *API)List(c *gin.Context){limit:=20;if v:=c.Query("limit");v!=""{fmt.Sscanf(v,"%d",&limit)};if limit<1{limit=1};if limit>100{limit=100};q:=a.db.Where("user_id = ?",middleware.Subject(c));if s:=c.Query("status");s!=""{q=q.Where("status = ?",s)};var rows []Job;if e:=q.Order("created_at DESC, id DESC").Limit(limit).Find(&rows).Error;e!=nil{c.JSON(500,gin.H{"code":"storage_error"});return};c.JSON(200,gin.H{"items":rows,"page":1,"limit":limit})}
func(a *API)Get(c *gin.Context){j,ok:=a.find(c);if ok{c.JSON(200,j)}}
func(a *API)Download(c *gin.Context){j,ok:=a.find(c);if !ok{return};if j.Status!="COMPLETED"||j.OutputObjectKey==nil{c.JSON(409,gin.H{"code":"result_not_ready","message":"Video result is not available"});return};u,e:=a.public.PresignedGetObject(c,a.cfg.ResultBucket,*j.OutputObjectKey,a.cfg.PresignTTL,url.Values{});if e!=nil{c.JSON(503,gin.H{"code":"download_unavailable"});return};c.JSON(200,gin.H{"downloadUrl":u.String(),"expiresInSeconds":int(a.cfg.PresignTTL.Seconds())})}
